#include "Source/DSP/SeptumEngine.cpp"
#include <iostream>
#include <iomanip>
#include <stdexcept>
int main() {
  int cases=0, untouched=0; double maxClock=0;
  const std::array<septum::Waveform,6> waves{septum::Waveform::Saw,septum::Waveform::Square,septum::Waveform::PulseSquare,septum::Waveform::Triangle,septum::Waveform::Sine,septum::Waveform::Noise};
  saw_w4::Config candidate; candidate.enabled=true;candidate.phase=.217;
  for(int i=0;i<16;++i){candidate.negative[i]=.13*std::sin(i+.37);candidate.positive[i]=.09*std::cos(i+.61);}candidate.integrate();
  for(auto wave:waves)for(double inc:{1./256,.039,.125,.15,.25,.45})for(double start:{0.,.01,.49,.5,.875,.99})for(double offset:{0.,.1,.75})for(bool corrected:{false,true})for(int note:{60,91}){
    double p=start,q=start;std::uint32_t rn=1234567,rc=rn;septum::NoiseSource nn{},nc{};nn.prepare(44100);nc.prepare(44100);
    saw_w4::config={};auto original=septum::renderClassicWave(wave,p,inc,.37,rn,nn,corrected,offset,note);
    saw_w4::config=candidate;auto trial=septum::renderClassicWave(wave,q,inc,.37,rc,nc,corrected,offset,note);
    double expected=start+inc;bool wrap=expected>=1.;if(wrap)expected-=1.;
    double expectedOffset=wrap?expected/std::max(1e-9,inc):0.;
    if(p!=q||q!=expected||original.wrapped!=trial.wrapped||trial.wrapped!=wrap||original.wrapOffset!=trial.wrapOffset||trial.wrapOffset!=expectedOffset||rn!=rc)throw std::runtime_error("Clock or RNG changed");
    if(wave!=septum::Waveform::Saw||!corrected){if(original.value!=trial.value)throw std::runtime_error("Untargeted sample changed");++untouched;}
    ++cases;
  }
  std::cout<<"{\"status\":\"passed\",\"actual_renderClassicWave_calls\":"<<2*cases<<",\"paired_clock_checks\":"<<cases<<",\"exact_untargeted_sample_checks\":"<<untouched<<",\"phase_offset\":0.217,\"maximum_clock_difference\":"<<maxClock<<"}\n";
}
